"""Refresh the bug-report integration version options from published releases."""

from __future__ import annotations

import argparse
import json
import re
import subprocess
from pathlib import Path

BUG_REPORT_PATH = Path(".github/ISSUE_TEMPLATE/bug_report.yml")
START_SENTINEL = "        # <!-- AUTOGENERATED_VERSION_OPTIONS_START -->"
END_SENTINEL = "        # <!-- AUTOGENERATED_VERSION_OPTIONS_END -->"
TAG = re.compile(r"^v(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)(?:-beta\.[1-9]\d*)?$")


def release_tags(releases: list[dict]) -> list[str]:
    """Keep up to 15 unique stable/beta tags in GitHub's newest-first order."""
    tags: list[str] = []
    for release in releases:
        tag = release.get("tagName")
        if isinstance(tag, str) and TAG.fullmatch(tag) and tag not in tags:
            tags.append(tag)
            if len(tags) == 15:
                break
    return tags


def render_options(content: str, tags: list[str]) -> str:
    """Replace exactly one marked block, retaining unreleased/manual options."""
    if content.count(START_SENTINEL) != 1 or content.count(END_SENTINEL) != 1:
        raise ValueError("Expected exactly one version-options sentinel pair")
    start, end = content.index(START_SENTINEL), content.index(END_SENTINEL)
    if end <= start:
        raise ValueError("Version-options sentinels are out of order")
    options = [*tags, "Development branch (unreleased)", "Other / Older"]
    block = "\n".join(f"        - {option}" for option in options)
    return content[:start] + START_SENTINEL + "\n" + block + "\n" + content[end:]


def main() -> None:
    """Fetch releases read-only; submit changed form through a normal dev PR."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", required=True)
    args = parser.parse_args()
    result = subprocess.run(
        ["gh", "release", "list", "--repo", args.repo, "--limit", "100", "--exclude-drafts", "--json", "tagName"],
        check=True,
        capture_output=True,
        text=True,
    )
    content = BUG_REPORT_PATH.read_text(encoding="utf-8")
    updated = render_options(content, release_tags(json.loads(result.stdout)))
    if updated != content:
        BUG_REPORT_PATH.write_text(updated, encoding="utf-8")
        print("Updated bug-report version options; include this change in a PR to dev.")
    else:
        print("Bug-report version options are already current.")


if __name__ == "__main__":
    main()
